import { readFileSync } from "node:fs";
import * as path from"node:path";
import { defineConfig } from "rolldown";

const licensePath = path.join(import.meta.dirname, "THIRD-PARTY-LICENSES");
const licenseText = readFileSync(licensePath, "utf8");

function formatComment(text) {
	const trimmed = text.trim();
	const lines = trimmed.split("\n").map(line => "* " + line);
	return `/*\n${lines.join("\n")}\n*/\n`;
}

const noteComment = `/*
 * This file is automatically generated by Rolldown.
 * DO NOT EDIT THIS FILE MANUALLY.
 * Instead, edit the files in the \`src\` directory of the \`develop\` branch.
*/
`;

export default defineConfig({
	input: "src/SpeakiMod.js",
	output: {
		file: "SpeakiMod.js",
		format: "es",
		banner: noteComment + formatComment(licenseText),
		sourcemap: true,
		sourcemapBaseUrl: "https://raw.githubusercontent.com/DJTOMATO/SpeakiRPG/refs/heads/main"
	}
});
